// In AdminDriverCard.tsx or FleetMap popup
async function handleCall(driverId: string, type: 'voice' | 'video') {
  try {
    setIsLoading(true);
    const res = await fetch('/api/calls/initiate', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ calleeId: driverId, type }),
    });
    if (!res.ok) throw new Error('Failed to initiate call');
    const { roomName, token, liveKitUrl } = await res.json();
    // Cache token so call page doesn't need a second round-trip
    sessionStorage.setItem(`livekit_token_${roomName}`, token);
    sessionStorage.setItem(`livekit_url_${roomName}`, liveKitUrl);
    router.push(`/admin/calls/${roomName}?type=${type}`);
  } catch (e) {
    toast.error('Could not start call. Please try again.');
  } finally {
    setIsLoading(false);
  }
}

